interface Fixture {
  name: string;
  flags: Record<string, string | boolean>;
  /** The managed keys of the file, merged with the environment (what setup loads). */
  file: Values;
  secrets: Partial<Record<'DISCORD_TOKEN' | 'DISCORD_CLIENT_SECRET' | 'TUNNEL_TOKEN' | 'DUCKDNS_TOKEN', string>>;
  host: { platform: NodeJS.Platform; isRoot: boolean; docker: boolean; nat: 'home' | 'vps' | null };
  env?: Record<string, string>;
  locale: Locale;
  compiled: boolean;
  expected: { values: Values; errors: string[]; missing: string[] };
}

function hostOf(h: Fixture['host']): HostInfo {
  return {
    kind: h.docker ? 'docker' : h.platform === 'win32' ? 'windows' : h.isRoot ? 'linux-root' : 'linux-user',
    platform: h.platform, arch: 'x64', isRoot: h.isRoot, docker: h.docker,
    osName: h.platform === 'win32' ? 'Windows 11' : 'Debian GNU/Linux 12 (bookworm)',
    publicIp: '203.0.113.9', nat: h.nat === null ? null : h.nat === 'vps' ? VPS_NAT : NAT,
  };
}

function modelEnv(o: { file?: Values; host?: HostInfo | null; offline?: boolean; langFlag?: boolean; compiled?: boolean; docker?: boolean } = {}): ModelEnv {
  const host = o.host === undefined ? hostOf({ platform: 'linux', isRoot: true, docker: false, nat: 'home' }) : o.host;
  return {
    platform: host?.platform ?? 'linux', isRoot: host?.isRoot ?? true, docker: o.docker ?? host?.docker ?? false,
    compiled: !!o.compiled, offline: !!o.offline, langFlag: !!o.langFlag,
    flags: { noService: false, noUpnp: false, noFirewall: false, noDoctor: false },
    file: o.file ?? {}, host, unprivilegedPortStart: null, lookups: {},
  };
}

const baseOf = (env: ModelEnv, locale: Locale = 'en'): ResolveBase => ({ file: env.file, host: env.host, locale, langFlag: env.langFlag, docker: env.docker, compiled: env.compiled });
const text = (locale: Locale, t: Text) => ('raw' in t ? t.raw : q(locale, t.key, t.params));
/** Values as the file holds them: an empty value is no key. */
const clean = (v: Values) => Object.fromEntries(Object.entries(v).filter(([, x]) => x !== '' && x !== undefined).sort(([a], [b]) => a.localeCompare(b)));

