function fixtureEnv(f: Fixture) {
  const env = modelEnv({ file: f.file, host: hostOf(f.host), offline: !!f.flags['no-discord-check'], langFlag: !!f.flags.lang, compiled: f.compiled, docker: f.host.docker });
  return { env, base: baseOf(env, f.locale) };
}

const flagRun = (f: Fixture) => answersFromFlags(f.flags as SetupFlagValues, fixtureEnv(f).env, {
  secrets: f.secrets, locale: f.locale, lenient: false, advanced: !!f.flags.advanced, env: f.env,
});
const fixture = (name: string) => {
  const f = FIXTURES.find((x) => x.name === name);
  if (!f) throw new Error(`no fixture ${name}`);
  return f;
};

describe('answersFromFlags: the non-interactive run', () => {
  for (const f of FIXTURES) {
    test(f.name, () => {
      const { env, base } = fixtureEnv(f);
      const r = flagRun(f);
      expect(r.errors.map((t) => text(f.locale, t))).toEqual(f.expected.errors);
      expect(r.missing).toEqual(f.expected.missing);
      if (!f.expected.errors.length) expect(clean(resolveValues(r.answers, env, base))).toEqual(f.expected.values);
    });
  }

  test('DISCORD_CLIENT_ID survives online runs where clientId is not a question', () => {
    for (const name of ['online run with --client-id', 'online re-run whose file has DISCORD_CLIENT_ID', 'online re-run with a new --client-id']) {
      const f = fixture(name);
      const { env, base } = fixtureEnv(f);
      const r = flagRun(f);
      expect(flowIds(r.answers, env)).not.toContain('clientId');
      expect(resolveValues(r.answers, env, base).DISCORD_CLIENT_ID).toBe(f.expected.values.DISCORD_CLIENT_ID!);
    }
    expect(fixture('online run with --client-id').expected.values.DISCORD_CLIENT_ID).toBe(APP);
    expect(fixture('online re-run with a new --client-id').expected.values.DISCORD_CLIENT_ID).toBe('555555555555555555');
    // Without one nothing is made up: the install reads it from the token.
    const f = fixture('online run without --client-id');
    expect(resolveValues(flagRun(f).answers, fixtureEnv(f).env, fixtureEnv(f).base).DISCORD_CLIENT_ID).toBeUndefined();
  });

  test('hidden answers appear only where the questions cannot spell the file', () => {
    const hidden = (name: string) => {
      const a = flagRun(fixture(name)).answers;
      return { publicUrl: a.publicUrl, httpPort: a.httpPort, httpsPortDirect: a.httpsPortDirect, pinnedIp: a.pinnedIp };
    };
    const none = { publicUrl: undefined, httpPort: undefined, httpsPortDirect: undefined, pinnedIp: undefined };
    expect(hidden('home --duckdns-domain: HTTPS on 8443')).toEqual(none);
    expect(hidden('home own domain with --advanced: 80/443')).toEqual(none);
    expect(hidden('VPS tunnel')).toEqual(none);
    expect(hidden('custom direct ports on a VPS')).toEqual({ ...none, httpPort: '8080', httpsPortDirect: '8443' });
    expect(hidden('VPS re-run keeps custom direct ports')).toEqual({ publicUrl: 'https://telinha.example.com:8443', httpPort: '8080', httpsPortDirect: '8443', pinnedIp: undefined });
    expect(hidden('--node-ip on an own domain pins it')).toEqual({ ...none, pinnedIp: '198.51.100.7' });
  });

  test('a VPS never asks a router: UPNP is off there even with --upnp auto', () => {
    const env = modelEnv({ host: hostOf({ platform: 'linux', isRoot: true, docker: false, nat: 'vps' }) });
    const r = answersFromFlags({ host: 'vps', 'public-url': URL_, upnp: 'auto', guild: GUILD, role: ROLE, channels: CHANNEL }, env, {
      secrets: { DISCORD_TOKEN: TOK, DISCORD_CLIENT_SECRET: SEC }, locale: 'en', lenient: false, advanced: false,
    });
    expect(r.errors).toEqual([]);
    expect(resolveValues(r.answers, env, baseOf(env)).UPNP).toBe('off');
  });
});

describe('answersFromFlags: flags next to a terminal (lenient)', () => {
  const lenient = (flags: SetupFlagValues, o: { file?: Values; secrets?: Fixture['secrets']; locale?: Locale } = {}) =>
    answersFromFlags(flags, modelEnv({ file: o.file }), { secrets: o.secrets ?? {}, locale: o.locale ?? 'en', lenient: true, advanced: !!flags.advanced });

  test('never missing; each flag the default of its question, on both address branches', () => {
    const r = lenient({ 'duckdns-domain': 'My-Group.duckdns.org', 'https-port': '9443', guild: GUILD, channels: ` ${CHANNEL},`, upnp: 'off' });
    expect(r.missing).toEqual([]);
    expect(r.errors).toEqual([]);
    expect(r.answers).toEqual({ duckName: 'my-group', vpsAddress: 'duckdns', homeCf: 'no', httpsPort: '9443', upnp: 'off', guild: GUILD, channels: [CHANNEL] });
    expect(lenient({ 'duckdns-domain': 'x', advanced: true }).answers).toEqual({ duckName: 'x', vpsAddress: 'duckdns', homeCf: 'advanced', homeAdvanced: 'ports', advancedAddress: 'duckdns' });
    expect(lenient({ ingress: 'tunnel', 'public-url': 'https://t.example.com/' }).answers).toEqual({ homeCf: 'yes', vpsAddress: 'tunnel', tunnelHost: 't.example.com' });
    expect(lenient({ ingress: 'external', 'public-url': 'https://x.example.com:8443/' }).answers).toEqual({ vpsAddress: 'external', externalUrl: 'https://x.example.com:8443' });
    expect(lenient({ 'public-url': 'https://203-0-113-9.sslip.io', 'node-ip': '203.0.113.9' }).answers).toEqual({ vpsAddress: 'sslip', nodeIp: '203.0.113.9' });
    expect(lenient({ 'public-url': URL_, advanced: true }).answers).toEqual({ domain: 'telinha.example.com', vpsAddress: 'domain', homeCf: 'advanced', homeAdvanced: 'ports', advancedAddress: 'domain' });
  });

  test('--https-port alone is the home port question\'s default; 80/443 never are', () => {
    expect(lenient({ 'https-port': '9443' }).answers).toEqual({ httpsPort: '9443' });
    expect(lenient({ 'https-port': '443' }).answers).toEqual({});
  });

  test('secrets read by the caller become kept values; a pasted install command keeps the token', () => {
    const r = lenient({}, { secrets: { DISCORD_TOKEN: TOK, DISCORD_CLIENT_SECRET: SEC, DUCKDNS_TOKEN: DUCKTOK, TUNNEL_TOKEN: `cloudflared service install ${TUNNEL}` } });
    expect(r.answers).toEqual({ discordToken: TOK, clientSecret: SEC, duckToken: DUCKTOK, tunnelToken: TUNNEL });
  });

  test('a rule error is reported (a notice on screen) and its flags are left out of the defaults', () => {
    const r = lenient({ host: 'home', 'public-url': URL_, guild: '12', command: 'sala' });
    expect(r.errors.map((t) => text('en', t))).toEqual([
      'at home Telinha never relies on ports 80/443: use --duckdns-domain (HTTPS on a high port), --ingress tunnel, or --advanced to confirm you opened 80 and 443 yourself (or run your own proxy); on a rented server pass --host vps',
      '--guild: 12 is not valid (want a Discord id: 17-20 digits)',
    ]);
    expect(r.answers).toEqual({ hosting: 'home', command: 'sala' });
    // Without a stated hosting the home rules wait for the hosting question.
    expect(lenient({ 'public-url': URL_ }).errors).toEqual([]);
    // A home file states it.
    const homeFile = { HOSTING: 'home', INGRESS: 'direct', ACME_DNS: 'duckdns', DUCKDNS_DOMAIN: 'x', DDNS_PROVIDER: 'duckdns', HTTP_PORT: '0', HTTPS_PORT: '8443', PUBLIC_URL: 'https://x.duckdns.org:8443' };
    expect(lenient({ 'public-url': URL_ }, { file: homeFile }).errors).toHaveLength(1);
    expect(lenient({ 'public-url': URL_ }, { file: homeFile }).answers).toEqual({});
    // Bad values never become defaults.
    const bad = lenient({ host: 'moon', upnp: 'maybe', 'media-tcp': '70000', 'duckdns-domain': 'no_way', ingress: 'magic' });
    expect(bad.errors).toHaveLength(5);
    expect(bad.answers).toEqual({});
    expect(text('pt-BR', lenient({ guild: '12' }, { locale: 'pt-BR' }).errors[0]!)).toBe('--guild: 12 não vale (esperado um id do Discord: 17-20 dígitos)');
  });

  test('--media-tcp / --media-udp change the ports', () => {
    expect(lenient({ 'media-tcp': '50000' }).answers).toEqual({ mediaPorts: 'change', mediaTcp: '50000' });
  });
});

describe('resolveValues', () => {
  const vps = modelEnv({ host: hostOf({ platform: 'linux', isRoot: true, docker: false, nat: 'vps' }) });
  const home = modelEnv();
  const resolve = (a: Answers, env = home) => clean(resolveValues(a, env, baseOf(env)));
  const discord: Answers = { discordToken: TOK, clientSecret: SEC, clientId: APP, guild: GUILD, role: ROLE, channels: [CHANNEL], command: 'telinha', group: '' };
  const d = { DISCORD_TOKEN: TOK, DISCORD_CLIENT_ID: APP, DISCORD_CLIENT_SECRET: SEC, GUILD_ID: GUILD, ROLE_ID: ROLE, CHANNEL_IDS: CHANNEL, COMMAND_NAME: 'telinha' };

  test('each address choice writes its columns', () => {
    expect(resolve({ ...discord, hosting: 'home', homeCf: 'yes', tunnelToken: TUNNEL, tunnelHost: 't.example.com', upnp: 'auto', mediaPorts: 'keep' }))
      .toEqual({ ...d, HOSTING: 'home', INGRESS: 'tunnel', TUNNEL_TOKEN: TUNNEL, PUBLIC_URL: 'https://t.example.com', UPNP: 'auto' });
    expect(resolve({ ...discord, hosting: 'home', homeCf: 'no', duckName: 'my-group', duckToken: DUCKTOK, httpsPort: '8443', upnp: 'auto' })).toEqual({
      ...d, HOSTING: 'home', INGRESS: 'direct', PUBLIC_URL: 'https://my-group.duckdns.org:8443', HTTP_PORT: '0', HTTPS_PORT: '8443', ACME_DNS: 'duckdns',
      DDNS_PROVIDER: 'duckdns', DUCKDNS_DOMAIN: 'my-group', DUCKDNS_TOKEN: DUCKTOK, UPNP: 'auto',
    });
    expect(resolve({ hosting: 'home', homeCf: 'advanced', homeAdvanced: 'ports', advancedAddress: 'domain', domain: 't.example.com', upnp: 'off' }))
      .toEqual({ HOSTING: 'home', INGRESS: 'direct', PUBLIC_URL: 'https://t.example.com', HTTP_PORT: '80', HTTPS_PORT: '443', UPNP: 'off' });
    expect(resolve({ hosting: 'home', homeCf: 'advanced', homeAdvanced: 'proxy', externalUrl: 'https://x.example.com:8443/', upnp: 'auto' }))
      .toEqual({ HOSTING: 'home', INGRESS: 'external', PUBLIC_URL: 'https://x.example.com:8443', UPNP: 'auto' });
    expect(resolve({ hosting: 'vps', vpsAddress: 'duckdns', duckName: 'my-group', duckToken: DUCKTOK }, vps)).toEqual({
      HOSTING: 'vps', INGRESS: 'direct', PUBLIC_URL: 'https://my-group.duckdns.org', HTTP_PORT: '80', HTTPS_PORT: '443', DDNS_PROVIDER: 'duckdns', DUCKDNS_DOMAIN: 'my-group', DUCKDNS_TOKEN: DUCKTOK, UPNP: 'off',
    });
    expect(resolve({ hosting: 'vps', vpsAddress: 'sslip' }, vps))
      .toEqual({ HOSTING: 'vps', INGRESS: 'direct', PUBLIC_URL: 'https://203-0-113-9.sslip.io', HTTP_PORT: '80', HTTPS_PORT: '443', LIVEKIT_NODE_IP: '203.0.113.9', UPNP: 'off' });
    expect(resolve({ hosting: 'vps', vpsAddress: 'sslip', nodeIp: '198.51.100.7' }, modelEnv({ host: null })))
      .toMatchObject({ PUBLIC_URL: 'https://198-51-100-7.sslip.io', LIVEKIT_NODE_IP: '198.51.100.7' });
  });

  test('a mode switch clears every key of the old mode; what no question covers stays', () => {
    const duckFile = {
      HOSTING: 'home', INGRESS: 'direct', PUBLIC_URL: 'https://my-group.duckdns.org:8443', HTTP_PORT: '0', HTTPS_PORT: '8443', ACME_DNS: 'duckdns',
      DDNS_PROVIDER: 'duckdns', DUCKDNS_DOMAIN: 'my-group', DUCKDNS_TOKEN: DUCKTOK, LIVEKIT_NODE_IP: '198.51.100.7', UPNP: 'auto', COOKIE_SECRET: COOKIE,
    };
    expect(resolve({ hosting: 'home', homeCf: 'yes', tunnelToken: TUNNEL, tunnelHost: 't.example.com', upnp: 'auto' }, modelEnv({ file: duckFile })))
      .toEqual({ HOSTING: 'home', INGRESS: 'tunnel', PUBLIC_URL: 'https://t.example.com', TUNNEL_TOKEN: TUNNEL, UPNP: 'auto', COOKIE_SECRET: COOKIE });
    const tunnelFile = modelEnv({ file: { HOSTING: 'vps', INGRESS: 'tunnel', TUNNEL_TOKEN: TUNNEL, PUBLIC_URL: 'https://t.example.com', UPNP: 'off' }, host: vps.host });
    expect(resolve({ hosting: 'vps', vpsAddress: 'domain', domain: 'x.example.com' }, tunnelFile))
      .toEqual({ HOSTING: 'vps', INGRESS: 'direct', PUBLIC_URL: 'https://x.example.com', HTTP_PORT: '80', HTTPS_PORT: '443', UPNP: 'off' });
  });

  test('answers on a branch left behind, and questions not shown, are ignored', () => {
    const a: Answers = { hosting: 'home', homeCf: 'yes', tunnelToken: TUNNEL, tunnelHost: 't.example.com', vpsAddress: 'sslip', domain: 'x.example.com', duckName: 'old', upnp: 'auto' };
    expect(resolve(a)).toEqual({ HOSTING: 'home', INGRESS: 'tunnel', PUBLIC_URL: 'https://t.example.com', TUNNEL_TOKEN: TUNNEL, UPNP: 'auto' });
    // Not compiled: no updates question, so no AUTO_UPDATE from an answer.
    expect(resolve({ autoUpdate: 'off' }).AUTO_UPDATE).toBeUndefined();
    expect(resolve({ autoUpdate: 'off' }, modelEnv({ compiled: true })).AUTO_UPDATE).toBe('off');
    expect(resolve({}, modelEnv({ file: { AUTO_UPDATE: 'off' } })).AUTO_UPDATE).toBe('off');
    // The client id is a question only offline; online it still counts (it comes from the token).
    expect(flowIds({ clientId: APP }, home)).not.toContain('clientId');
    expect(resolve({ clientId: APP }).DISCORD_CLIENT_ID).toBe(APP);
  });

  test('media ports: defaults stay commented, a change is written, the file\'s own kept', () => {
    expect(resolve({ mediaPorts: 'change', mediaTcp: '7881', mediaUdp: '7882' })).toEqual({ UPNP: 'off' });
    expect(resolve({ mediaPorts: 'change', mediaTcp: '50000', mediaUdp: '7882' })).toEqual({ MEDIA_TCP_PORT: '50000', UPNP: 'off' });
    const custom = modelEnv({ file: { MEDIA_UDP_PORT: '50001' } });
    expect(resolve({ mediaPorts: 'keep' }, custom)).toEqual({ MEDIA_UDP_PORT: '50001', UPNP: 'off' });
    // Changed back to the defaults, the key is commented again.
    expect(resolve({ mediaPorts: 'change', mediaTcp: '7881', mediaUdp: '7882' }, custom)).toEqual({ UPNP: 'off' });
  });

  test('LOCALE: the language answer, else --lang\'s locale, else the file', () => {
    expect(resolve({ lang: 'pt-BR' }).LOCALE).toBe('pt-BR');
    const flagged = modelEnv({ langFlag: true });
    expect(clean(resolveValues({ lang: 'en' }, flagged, baseOf(flagged, 'pt-BR'))).LOCALE).toBe('pt-BR');
    expect(resolve({ lang: 'en' }, modelEnv({ file: { LOCALE: 'pt-BR' } })).LOCALE).toBe('pt-BR');
  });

  test('webAddress: empty until the address is chosen', () => {
    expect(webAddress({ hosting: 'home' }, home, baseOf(home))).toBe('');
    expect(webAddress({ hosting: 'home', homeCf: 'no', duckName: 'x', httpsPort: '9443' }, home, baseOf(home))).toBe('https://x.duckdns.org:9443');
  });
});

describe('defaultAnswers: a re-run from the file', () => {
  const vpsHost = hostOf({ platform: 'linux', isRoot: true, docker: false, nat: 'vps' });
  const roundTrip = (file: Values, host: HostInfo | null = vpsHost) => {
    const env = modelEnv({ file, host });
    const a = defaultAnswers(env);
    return { a, values: clean(resolveValues(a, env, baseOf(env))) };
  };
  const D = { DISCORD_TOKEN: TOK, DISCORD_CLIENT_ID: APP, DISCORD_CLIENT_SECRET: SEC, GUILD_ID: GUILD, ROLE_ID: ROLE, CHANNEL_IDS: CHANNEL, COMMAND_NAME: 'telinha', COOKIE_SECRET: COOKIE, LIVEKIT_API_KEY: LKKEY, LIVEKIT_API_SECRET: LKSEC, LOCALE: 'en' };

  test('a fresh install: the machine suggests, nothing hidden', () => {
    const a = defaultAnswers(modelEnv());
    expect(a).toMatchObject({ hosting: 'home', homeCf: 'no', vpsAddress: 'domain', httpsPort: '8443', command: 'telinha', group: '', mediaPorts: 'keep', upnp: 'auto', autoUpdate: 'on' });
    for (const id of ['publicUrl', 'httpPort', 'httpsPortDirect', 'pinnedIp', 'domain', 'duckName', 'discordToken'] as const) expect(a[id]).toBeUndefined();
    expect(defaultAnswers(modelEnv({ host: vpsHost })).hosting).toBe('vps');
    expect(defaultAnswers(modelEnv({ host: null })).hosting).toBe('home');
  });

  test('files setup writes come back unchanged', () => {
    const files: Values[] = [
      { ...D, HOSTING: 'home', INGRESS: 'direct', PUBLIC_URL: 'https://my-group.duckdns.org:9443', HTTP_PORT: '0', HTTPS_PORT: '9443', ACME_DNS: 'duckdns', DDNS_PROVIDER: 'duckdns', DUCKDNS_DOMAIN: 'my-group', DUCKDNS_TOKEN: DUCKTOK, UPNP: 'off' },
      { ...D, HOSTING: 'home', INGRESS: 'tunnel', PUBLIC_URL: 'https://t.example.com', TUNNEL_TOKEN: TUNNEL, UPNP: 'auto' },
      { ...D, HOSTING: 'home', INGRESS: 'direct', PUBLIC_URL: 'https://t.example.com', HTTP_PORT: '80', HTTPS_PORT: '443', UPNP: 'auto' },
      { ...D, HOSTING: 'home', INGRESS: 'direct', PUBLIC_URL: 'https://x.duckdns.org', HTTP_PORT: '80', HTTPS_PORT: '443', DDNS_PROVIDER: 'duckdns', DUCKDNS_DOMAIN: 'x', DUCKDNS_TOKEN: DUCKTOK2, UPNP: 'auto' },
      { ...D, HOSTING: 'home', INGRESS: 'external', PUBLIC_URL: 'https://x.example.com:8443', UPNP: 'auto' },
      { ...D, HOSTING: 'vps', INGRESS: 'direct', PUBLIC_URL: URL_, HTTP_PORT: '80', HTTPS_PORT: '443', UPNP: 'off', MEDIA_TCP_PORT: '50000', AUTO_UPDATE: 'off', GROUP_NAME: 'Turma' },
      { ...D, HOSTING: 'vps', INGRESS: 'direct', PUBLIC_URL: 'https://telinha.example.com:8443', HTTP_PORT: '8080', HTTPS_PORT: '8443', LIVEKIT_NODE_IP: '198.51.100.7', UPNP: 'off' },
      { ...D, HOSTING: 'vps', INGRESS: 'direct', PUBLIC_URL: 'https://203-0-113-9.sslip.io', HTTP_PORT: '80', HTTPS_PORT: '443', LIVEKIT_NODE_IP: '203.0.113.9', UPNP: 'off' },
      { ...D, HOSTING: 'vps', INGRESS: 'tunnel', PUBLIC_URL: 'https://t.example.com', TUNNEL_TOKEN: TUNNEL, UPNP: 'off' },
    ];
    for (const file of files) expect(roundTrip(file).values).toEqual(clean(file));
  });

  test('custom direct ports, a pinned IP and an address with a port ride along as hidden answers', () => {
    const { a } = roundTrip({ ...D, HOSTING: 'vps', INGRESS: 'direct', PUBLIC_URL: 'https://telinha.example.com:8443', HTTP_PORT: '8080', HTTPS_PORT: '8443', LIVEKIT_NODE_IP: '198.51.100.7', UPNP: 'off' });
    expect(a).toMatchObject({ vpsAddress: 'domain', domain: 'telinha.example.com', httpPort: '8080', httpsPortDirect: '8443', pinnedIp: '198.51.100.7', publicUrl: 'https://telinha.example.com:8443' });
    // sslip.io follows the machine's IP: nothing pinned.
    expect(roundTrip({ HOSTING: 'vps', PUBLIC_URL: 'https://203-0-113-9.sslip.io', LIVEKIT_NODE_IP: '203.0.113.9' }).a.pinnedIp).toBeUndefined();
    // A DuckDNS home file keeps its port, and its token for its own name only.
    const duckFile = { HOSTING: 'home', INGRESS: 'direct', ACME_DNS: 'duckdns', HTTPS_PORT: '9443', HTTP_PORT: '0', DUCKDNS_DOMAIN: 'x', DDNS_PROVIDER: 'duckdns', DUCKDNS_TOKEN: DUCKTOK, PUBLIC_URL: 'https://x.duckdns.org:9443' };
    expect(roundTrip(duckFile, null).a).toMatchObject({ hosting: 'home', homeCf: 'no', duckName: 'x', duckToken: DUCKTOK, httpsPort: '9443' });
  });
});

describe('keepHidden', () => {
  const source: Answers = { hosting: 'vps', vpsAddress: 'domain', domain: 't.example.com', httpPort: '8080', httpsPortDirect: '8443', pinnedIp: '198.51.100.7', publicUrl: 'https://t.example.com:8443' };

  test('ports stay in a direct mode of the same hosting; the IP and the URL only while the address does', () => {
    expect(keepHidden({ ...source }, source)).toEqual({ httpPort: '8080', httpsPortDirect: '8443', pinnedIp: '198.51.100.7', publicUrl: 'https://t.example.com:8443' });
    expect(keepHidden({ ...source, domain: 'u.example.com' }, source)).toEqual({ httpPort: '8080', httpsPortDirect: '8443', pinnedIp: '198.51.100.7' });
    expect(keepHidden({ hosting: 'vps', vpsAddress: 'duckdns', duckName: 'x' }, source)).toEqual({ httpPort: '8080', httpsPortDirect: '8443' });
    expect(keepHidden({ hosting: 'vps', vpsAddress: 'tunnel' }, source)).toEqual({});
    expect(keepHidden({ hosting: 'home', homeCf: 'advanced', homeAdvanced: 'ports', advancedAddress: 'domain', domain: 't.example.com' }, source)).toEqual({});
  });
});
